async function run(){await db.initialize();console.log("Database initialized.");const e=db.models.exchangeMarket;if(e){const t=await e.findOne({where:{currency:"BTC",pair:"USDT"}});if(t){console.log(`Found BTC/USDT: id=${t.id}, status=${t.status}`);if(!t.status){t.status=!0;await t.save();console.log("Updated BTC/USDT status to true!")}}else console.log("BTC/USDT market not found in exchangeMarket table!");const a=[{currency:"ETH",pair:"USDT"},{currency:"SOL",pair:"USDT"},{currency:"LTC",pair:"USDT"},{currency:"XRP",pair:"USDT"}];for(const t of a){const a=await e.findOne({where:{currency:t.currency,pair:t.pair}});if(a){console.log(`Found ${t.currency}/${t.pair}: id=${a.id}, status=${a.status}`);if(!a.status){a.status=!0;await a.save();console.log(`Updated ${t.currency}/${t.pair} status to true!`)}}}}else console.error("exchangeMarket model not found!");process.exit(0)}require("dotenv").config({path:"../.env"});require("./module-alias-setup.js");const{db:db}=require("@b/db");run();